import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    num = data[0].strip()
    k = int(data[1].strip())
    if k < 0:
        k = 0
    stack = []
    for ch in num:
        while k > 0 and stack and stack[-1] > ch:
            stack.pop()
            k -= 1
        stack.append(ch)
    if k > 0:
        stack = stack[:-k]
    result = ''.join(stack).lstrip('0')
    if not result:
        result = '0'
    print(result)

if __name__ == "__main__":
    main()
